do $$ begin if not exists(select 1 from gd_private.runtime where project_ref in ('ztzpipgptticvliotbsc','tgvozhrkolcpszyyrgth')) then raise exception 'KNOWN_PROJECT_REQUIRED'; end if; end $$;
lock table public.gd_products in share row exclusive mode;
with source as (select * from jsonb_to_recordset($catalog$[{"name":"Hoa hồng · Sắc thương","occasion":"Tình yêu","price":490000,"stems":"Hoa hồng, lá trang trí","description":"Một lời yêu gần gũi với những cánh hồng nhiều lớp. Gợi ý tặng người thương hoặc kỉ niệm ngày bên nhau. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-01.jpg","active":false,"reference_only":true},{"name":"Tulip · Ngày trong veo","occasion":"Sinh nhật","price":690000,"stems":"Tulip theo mùa","description":"Dáng hoa thanh thoát, phù hợp người thích sự giản dị và hiện đại. Gợi ý cho sinh nhật hoặc một lời cảm ơn. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-02.jpg","active":false,"reference_only":true},{"name":"Mẫu đơn · Mây mềm","occasion":"Tình yêu","price":990000,"stems":"Mẫu đơn theo mùa","description":"Cánh hoa xếp đầy, tạo cảm giác mềm mại và trang nhã. Gợi ý kỉ niệm và những dịp muốn gửi một món quà nổi bật. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-03.jpg","active":false,"reference_only":true},{"name":"Hướng dương · Nắng mới","occasion":"Chúc mừng","price":450000,"stems":"Hướng dương, lá xanh","description":"Một sắc nắng dành cho khởi đầu mới, tốt nghiệp hoặc chúc mừng thành công. Thiết kế gợi ý lấy hướng dương làm điểm nhấn. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-04.jpg","active":false,"reference_only":true},{"name":"Hoa ly · Hương dịu","occasion":"Sinh nhật","price":590000,"stems":"Hoa ly theo mùa","description":"Dáng cánh mở rộng và màu sắc thanh lịch. Gợi ý cho người yêu hoa có hương; shop cần xác nhận màu và độ nở khi nhận đặt. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-05.jpg","active":false,"reference_only":true},{"name":"Cẩm chướng · Lời cảm ơn","occasion":"Sinh nhật","price":450000,"stems":"Cẩm chướng phối hoa hồng","description":"Cánh cẩm chướng mềm kết hợp hoa hồng cho một món quà ấm áp. Gợi ý gửi lời cảm ơn hoặc tặng người thân. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-06.jpg","active":false,"reference_only":true},{"name":"Đồng tiền · Vui rạng rỡ","occasion":"Chúc mừng","price":390000,"stems":"Hoa đồng tiền, hoa phụ","description":"Những bông hoa rộng mặt, tạo điểm nhấn tươi vui. Gợi ý chúc mừng khai trương nhỏ hoặc một ngày đáng nhớ. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-07.jpg","active":false,"reference_only":true},{"name":"Cẩm tú cầu · Mây vườn","occasion":"Sinh nhật","price":650000,"stems":"Cẩm tú cầu theo mùa","description":"Những cụm cánh nhỏ mang cảm giác đầy đặn và dịu dàng. Gợi ý cho người thích bó hoa mềm, cần shop xác nhận màu thực tế. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-08.jpg","active":false,"reference_only":true},{"name":"Hoa lan · Nét thanh","occasion":"Chúc mừng","price":790000,"stems":"Hoa lan phối cẩm tú cầu","description":"Dáng hoa thanh nhã cho một món quà trân trọng. Thiết kế gợi ý dùng lan làm trung tâm, quy cách do shop xác nhận trước khi bán. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-09.jpg","active":false,"reference_only":true},{"name":"Baby trắng · Lời thì thầm","occasion":"Tình yêu","price":490000,"stems":"Baby trắng phối hoa hồng","description":"Những chùm hoa nhỏ tạo khoảng thở quanh hoa hồng. Gợi ý lời nhắn nhẹ nhàng và một món quà không quá cầu kì. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-10.jpg","active":false,"reference_only":true},{"name":"Cúc nhỏ · Bình yên","occasion":"Sinh nhật","price":350000,"stems":"Cúc nhỏ, lá xanh","description":"Dáng hoa mộc mạc dành cho lời chúc bình an. Gợi ý tặng bạn bè hoặc mang một chút thiên nhiên vào góc bàn. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-11.jpg","active":false,"reference_only":true},{"name":"Thược dược · Vườn rực rỡ","occasion":"Chúc mừng","price":590000,"stems":"Thược dược theo mùa","description":"Nhiều lớp cánh tạo chiều sâu cho thiết kế. Gợi ý dịp chúc mừng hoặc người thích hoa có hình dáng nổi bật. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-12.jpg","active":false,"reference_only":true},{"name":"Mao lương · Cánh lụa","occasion":"Tình yêu","price":790000,"stems":"Mao lương, eucalyptus","description":"Những lớp cánh mỏng phối lá xanh cho cảm giác mềm và hiện đại. Gợi ý món quà kỉ niệm, phụ thuộc nguồn hoa theo mùa. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-13.jpg","active":false,"reference_only":true},{"name":"Freesia · Hương sớm","occasion":"Sinh nhật","price":650000,"stems":"Freesia theo mùa","description":"Những nhánh hoa nhỏ gợi một buổi sáng nhẹ nhàng. Gợi ý lời cảm ơn và các dịp tặng hoa thanh lịch. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-14.jpg","active":false,"reference_only":true},{"name":"Calla · Nét tối giản","occasion":"Cưới hỏi","price":790000,"stems":"Calla, lá trang trí","description":"Dáng hoa gọn, đường nét rõ, phù hợp phong cách tối giản. Gợi ý thiết kế cưới hoặc món quà cần vẻ trang nhã. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-15.jpg","active":false,"reference_only":true},{"name":"Lavender · Góc tím","occasion":"Sinh nhật","price":450000,"stems":"Lavender dạng bó","description":"Sắc tím nhẹ cho người thích một góc nhỏ yên tĩnh. Shop cần xác nhận dùng hoa tươi hay hoa khô và quy cách trước khi bật bán. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-16.jpg","active":false,"reference_only":true},{"name":"Cúc · Mùa dịu êm","occasion":"Chúc mừng","price":390000,"stems":"Cúc theo mùa","description":"Các lớp cánh tạo một thiết kế đầy và gần gũi. Gợi ý chúc mừng hoặc tặng người thân; màu được xác nhận theo nguồn hoa. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-17.jpg","active":false,"reference_only":true},{"name":"Cát tường · Lời chúc lành","occasion":"Sinh nhật","price":550000,"stems":"Cát tường, hoa phụ","description":"Cánh hoa mềm và thanh thoát cho lời chúc dịu dàng. Gợi ý sinh nhật, cảm ơn hoặc một ngày bình thường muốn gửi lời thương. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-18.jpg","active":false,"reference_only":true},{"name":"Hoa sen · Mộc an","occasion":"Sinh nhật","price":490000,"stems":"Hoa sen theo mùa","description":"Dáng hoa mộc, phù hợp người yêu vẻ tự nhiên. Thiết kế và độ nở cần shop xác nhận theo mùa, ảnh là tham khảo loài hoa. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-19.jpg","active":false,"reference_only":true},{"name":"Hồng môn · Dấu ấn","occasion":"Chúc mừng","price":590000,"stems":"Hồng môn, lá xanh","description":"Đường nét nổi bật, gợi ý cho một món quà chúc mừng có cá tính. Shop cần xác nhận màu, số cành và quy cách thực tế. Ảnh minh họa tham khảo, chưa phải ảnh sản phẩm thực tế của shop. Số cành, kích thước, giấy gói và giá cuối cùng sẽ được công bố khi mẫu được mở bán. Chăm hoa: đặt nơi thoáng mát, tránh nắng trực tiếp; hoa cắt cành cần nước sạch và thay nước thường xuyên.","image":"/flowers/reference-20.jpg","active":false,"reference_only":true}]$catalog$::jsonb) as x(name text,occasion text,price integer,stems text,description text,image text,active boolean,reference_only boolean)),
missing as (select * from source where not exists(select 1 from public.gd_products p where p.image=source.image)),
numbered as (select (select coalesce(max(id),0) from public.gd_products)+row_number() over(order by image) id,* from missing)
insert into public.gd_products(id,name,occasion,price,stems,description,image,active,reference_only) select id,name,occasion,price,stems,description,image,false,true from numbered;
commit;
select count(*) filter(where reference_only) reference_models,count(*) filter(where active) sale_models from public.gd_products;
